# -*- coding: utf-8 -*-
# src/utils/bash/bashParser.ts 的批注数据（第 45 批之二）
# 纯 TS 手写 bash 解析器：词法 → 递归下降语法 → tree-sitter-bash 兼容 AST

ANNOTATIONS = [
    (1, 'after', r'''文件头。这是一个纯 TypeScript 手写的 bash 解析器，产出与 tree-sitter-bash 兼容的 AST。下游（parser.ts、ast.ts、prefix.ts、ParsedCommand.ts）按字段名遍历这棵树。两个关键约定：startIndex/endIndex 是 UTF-8 字节偏移而非 JS 字符串下标；正确性用 3449 条输入的金标准语料（从 WASM 版解析器生成）对齐验证。为什么手写：摆脱 WASM 依赖、可控超时，同时保持 AST 形状逐字节兼容以便安全行走器复用。'''),
    (18, 'after', r'''TsNode：最小 AST 节点——类型名、原文切片、字节起止、子节点。text 永远等于对源串按字节范围切片的结果。'''),
    (22, 'after', r'''ParserModule：与 WASM 版解析器同形的接口（parse 返回 null 表示放弃）。换实现时下游无感。'''),
    (29, 'after', r'''50ms 墙钟上限——恶意/病态输入直接放弃返回 null。正确性测试可传 Infinity 关闭（否则 CI 抖动会造成偶发 null）。'''),
    (32, 'after', r'''节点数上限 5 万——深嵌套输入在 OOM 之前就被拦下。两个预算都在 mk（建节点）时统一检查。'''),
    (34, 'after', r'''模块单例：parse 直接指向本文件的 parseSource；READY 是已完成的 Promise，保持与异步初始化的 WASM 版 API 兼容。'''),
    (41, 'after', r'''ensureParserInitialized：纯 TS 无需异步初始化，返回即完成的 Promise——纯粹为了 API 兼容保留。'''),
    (46, 'after', r'''getParserModule：永远成功（无需 init）。调用方拿到的模块永不为 null。'''),
    (48, 'after', r'''分隔注释：词法器（Tokenizer）部分开始。'''),
    (67, 'after', r'''TokenType：16 种 token。注意 OP 涵盖所有多字符操作符（&& || ;; << >> 等）；DOLLAR 系列按后续字符细分（$( ${ $(( $' ）；LT_PAREN/GT_PAREN 是进程替换 <( >(。'''),
    (75, 'after', r'''Token：start/end 也是 UTF-8 字节偏移——与 AST 节点同一坐标系。'''),
    (77, 'after', r'''SPECIAL_VARS：bash 特殊变量 ? $ @ * # - ! _——$ 后跟这些字符走 special_variable_name 节点。'''),
    (85, 'after', r'''DECL_KEYWORDS：声明类内建（export/declare/typeset/readonly/local），后随变量赋值语法，需要专门的 declaration_command 节点。'''),
    (103, 'after', r'''SHELL_KEYWORDS：保留字全集（if/fi/case/esac 等）。在词法层面是 WORD，由语法层按位置决定是否当关键字。导出供别处判断。'''),
    (121, 'after', r'''Lexer：双坐标系状态——i 是 JS 字符串下标（charAt 用），b 是 UTF-8 字节偏移（AST 位置用）。ASCII 快路径两者相等；含非 ASCII 时惰性构建 byteTable（每个字符下标的字节偏移表）。heredocs 挂起待下一换行扫描正文。'''),
    (132, 'after', r'''HeredocPending：heredoc 的挂起记录——定界符、是否 <<-剥 tab、是否引号定界（决定正文要不要解析展开）、正文与结束行的字节范围。'''),
    (143, 'after', r'''makeLexer：初始状态，byteTable 惰性为 null。'''),
    (160, 'after', r'''advance：推进一个 JS 字符并同步字节偏移。按码点分支：ASCII 加 1、二字节加 2、高位代理对（与下一字符成对）加 4、其余加 3。'''),
    (164, 'after', r'''peek：带偏移的前看，越界返回空串。'''),
    (194, 'after', r'''byteAt：查/建字节偏移表。快路径：byteTable 未建且从未遇到非 ASCII 时字符下标即字节下标；首个非平凡查询触发整表构建（O(n) 一次，之后 O(1)）。代理对占两个字符下标但共享同一字节起点。'''),
    (220, 'after', r'''isWordChar：bash 单词字符集——字母数字加一堆不会引发操作符歧义的标点（/ . - + : @ % 等）。注意 * ? ! = [ ] 也算单词字符（glob 与下标语义），由上下文区分。'''),
    (224, 'after', r'''isWordStart：单词起始多允许一个反斜杠（转义起始）。'''),
    (245, 'after', r'''isBaseDigit：BASE#DIGITS 进制记法的数字集——字母数字加 @（bash 支持到 64 进制）。'''),
    (270, 'after', r'''isHeredocDelimChar：未加引号 heredoc 定界符的合法字符——bash 接受大多数非元字符（不只标识符），允许 ! - . + 等（如 <<!HEREDOC!），停在空白/重定向/管道/结构符。'''),
    (296, 'after', r'''skipBlanks：跳过空白与换行连接符。细节对齐 tree-sitter extras：CR 按空白处理（兼容 CRLF 输入）；反斜杠换行是行连接；反斜杠加空格/tab 是 tree-sitter 的 _whitespace 规则（转义空白）。'''),
    (302, 'before', r'''nextToken：上下文敏感的取词器。ctx=cmd 时 [ [[ { ! 是操作符（test 命令/组开始）；ctx=arg 时是普通单词字符（glob/下标）。这一个参数决定了大量歧义的走向。'''),
    (327, 'after', r'''操作符词法从最长匹配开始：三字符（<<< 与 <<-、;;& &>>）优先，两字符次之（&& || ;;& ;; ;& >> >& >| &> << <& 等），单字符兜底。顺序错了就会把 << 切成两个 <。'''),
    (443, 'after', r'''单字符操作符兜底：| & ; > < ( )。到这里的多字符组合全部尝试过了。'''),
    (472, 'after', r'''cmd 上下文专属：[[ 与 [ 开 test 命令；{ 后跟空白才算组开始（${var} 的 { 不算）；! 后跟空白是取反。arg 上下文里这些全是普通字符——glob 与下标因此不被误切。'''),
    (489, 'after', r'''SQUOTE：单引号串整段吞到闭引号（内部无转义），value 保留原文含引号——对应 AST 的 raw_string。'''),
    (527, 'after', r'''$ 家族：$(($(( 算术、$( 命令替换、${ 参数展开、$ 等 ANSI-C 串（内部转义字符也吞掉）、裸 $。每个变体是独立 token 类型，语法层各走各的分支。'''),
    (532, 'after', r'''BACKTICK：反引号只出单字符 token，配对由语法层 inBacktick 深度计数处理。'''),
    (549, 'after', r'''文件描述符前缀：数字紧跟 > 或 < 时（如 2>/dev/null）切成独立 WORD——否则 2 会被当普通参数。'''),
    (591, 'after', r'''nextToken 收尾：普通单词扫描（内部处理反斜杠转义与行连接，EOF 处孤立反斜杠留给兄弟 ERROR 节点——对齐 tree-sitter）；纯数字串标 NUMBER；全不认识的字符当单字符 WORD。'''),
    (593, 'after', r'''分隔注释：语法器（Parser）部分开始。递归下降 + 回溯（saveLex/restoreLex）。'''),
    (608, 'after', r'''ParseState：语法器全局状态——词法器、源串与字节长、isAscii 快路径标记、节点计数与墙钟 deadline（预算控制）、inBacktick 嵌套深度、stopToken（[ 回溯时让 parseSimpleCommand 在 ] 前停下）。'''),
    (631, 'after', r'''parseSource：入口。构建状态、解析 program、被预算中止（aborted 标记）或抛异常（如 budget/timeout）都返回 null——调用方必须处理 null（回退安全判定）。'''),
    (645, 'after', r'''byteLengthUtf8：整串 UTF-8 字节数，一次扫完，顺带判定 isAscii。'''),
    (657, 'after', r'''checkBudget：节点计数 +1；超 5 万抛 budget；每 128 个节点查一次墙钟超 deadline 抛 timeout——用位掩码把昂贵的时间查询摊薄 128 倍。'''),
    (675, 'after', r'''mk：建节点统一入口。先过预算检查，再按字节范围切原文（ASCII 直接 slice，非 ASCII 走二分查找）。'''),
    (700, 'after', r'''sliceBytes：字节范围 → 原文切片。非 ASCII 时用 byteTable 两次二分定位字符下标再 slice。'''),
    (704, 'after', r'''leaf：从 token 直接造叶子节点（无子节点）。'''),
    (752, 'after', r'''parseProgram：顶层循环。先跳过前导空白换行定程序起点；主循环里 NEWLINE 跳过、COMMENT 收为 comment 叶子、其余交 parseStatements；解析失败时发 ERROR 节点并跳一个 token（错误恢复）；顶层孤立的 ;; 被静默吞掉（对齐 tree-sitter，但保留安全性——粘贴残留的 ; 是危险信号所以留 ERROR）。程序范围含尾部空白，对齐 tree-sitter。'''),
    (762, 'after', r'''saveLex/restoreLex：回溯原语。i 和 b 打包进一个数字（b<<16 | i）——每次回溯零堆分配。'''),
    (769, 'before', r'''parseStatements：分号/与号/换行分隔的语句序列。注意 ; 与 & 是平铺的兄弟叶子（不包 list 节点——只有 && || 才有 list）。terminator 指定本层的闭合符（) } 等）；then/fi/done/esac 等关键字也是隐式终止。换行处是 heredoc 正文的扫描时机。'''),
    (871, 'after', r'''parseStatements 收尾：分隔符后若无内容（trailing separator）则不收入；内层闭合符前的处理保持原样。返回平铺列表。'''),
    (879, 'before', r'''parseAndOr：&& || 连接的管道链，左结合。tree-sitter 怪癖：末尾管道带重定向时整个 list 会被 wrapped_statement 包住——a > x && b > y 变成 redirected_statement(list(...), >y)，这里精确复刻该形状。'''),
    (919, 'after', r'''parseAndOr 收尾：右侧解析失败（如 && 后直接 EOF）时把操作符与左侧包成残缺 list——错误输入也要有形状。'''),
    (930, 'after', r'''skipNewlines：跨行吞换行（管道符后的续行）。'''),
    (938, 'before', r'''parsePipeline：| 或 |& 连接的命令链，平铺子节点加操作符叶子。tree-sitter 怪癖：管道中段的尾部重定向会提升包裹前段——a | b 2>nul | c 变成 pipeline(redirected_statement(pipeline(a,|,b), 2>nul), |, c)，这里同样复刻。'''),
    (992, 'after', r'''parsePipeline 收尾：只有一个片段时直接返回该片段（不包 pipeline 节点）。'''),
    (995, 'before', r'''parseCommand：单条命令分派——取反、子 shell、算术 ((、花括号组、test 命令、控制结构关键字（if/while/for/case/function/声明类/unset），最后回落到简单命令。每类完成后再试尾部重定向。'''),
    (1081, 'before', r'''[ / [[ test 命令：先按表达式解析；没到闭合符就回溯改按 redirected_statement 解析（处理 [ ! cmd -v go &>/dev/null ] 这种内含重定向的写法），stopToken 机制防止 ] 被简单命令吃掉；两路都不行再回退表达式结果。闭合符缺失时补零宽节点保持形状。'''),
    (1116, 'after', r'''test 命令分支收尾。test_command 的子节点：开括号、表达式、闭括号。'''),
    (1131, 'after', r'''关键字分派收尾：if/while/until/for/select/case 各进对应解析器并允许尾部重定向；function 与声明类（export 等）、unset 同理。没命中任何关键字的 WORD 回退为简单命令。'''),
    (1135, 'after', r'''parseCommand 收尾。'''),
    (1141, 'before', r'''parseSimpleCommand：[赋值]* 单词 [参数|重定向]*。只有赋值没有命令时返回 variable_assignment（单个）或 variable_assignments（多个）；只有重定向时返回 redirected_statement。这里还内嵌了 name() { ... } 形式的函数定义识别。'''),
    (1267, 'after', r'''命令名之后的重定向是贪婪的（语法规则 repeat1(_literal)）——一旦出现重定向，后续字面量按 prec.left 都挂到重定向上：grep 2>/dev/null -q foo 里 -q foo 会被 file_redirect 吃掉。但重定向出现之前解析的参数仍归命令（cat a b > out）。'''),
    (1281, 'after', r'''出现过 file_redirect 后命令参数立即终止——语法规则不允许命令名之后还有参数跟在重定向后，剩余部分全部属于 redirected_statement 的 file_redirect 子节点。'''),
    (1334, 'after', r'''两类 zsh 风格输入的 ERROR 包装（bash 里都是语法错）：孤立 =（echo =(cmd) 的进程替换）与紧贴 ( 的单词（*.(e:cmd:) 这类 glob 限定符）。对齐 tree-sitter 的恢复行为——ERROR 节点让安全行走器 fail closed。'''),
    (1354, 'after', r'''前置换向（2>&1 cat、<<<str cmd）放进 command 节点内部、排在 command_name 之前——对齐语法规则，不进 redirected_statement。'''),
    (1404, 'after', r'''parseSimpleCommand 收尾：heredoc 重定向当场扫描正文并填 body/end 节点；普通重定向包 redirected_statement；heredoc 场景的范围起点要与前置换向取 min。'''),
    (1406, 'before', r'''maybeRedirect：复合结构（子 shell/组/控制语句）后的尾部重定向包装。herestring 默认不收（allowHerestring 控制）——复合语句后的 <<< 语义歧义。'''),
    (1429, 'after', r'''maybeRedirect 收尾。'''),
    (1431, 'before', r'''tryParseAssignment：变量赋值识别——标识符（可带 [下标]）后跟 = 或 +=。值可以是数组 (a b c) 或普通词。名字与值都建节点，下标包 subscript 节点。'''),
    (1519, 'after', r'''tryParseAssignment 收尾：值缺省时（如 A= 后直接换行）只有名字与操作符两个子节点。'''),
    (1527, 'before', r'''parseSubscriptIndexInline：${a[...]} 下标的算术解析——${a[1+2]} 是二元表达式、${a[++i]} 是一元、${a[(($n+1))]} 包 compound_statement；@ 或 * 单独出现是关联数组全键（word）。'''),
    (1559, 'after', r'''注意裸标识符在 subscript 里走 word 模式而非 var——对齐 tree-sitter 的 ${words[++counter]} 形状。'''),
    (1581, 'after', r'''parseSubscriptIndex：旧版按字节范围预扫的实现，保留给调用方（tryParseAssignment 还在用）——只识别纯数字、$var、特殊变量，其余当 word。'''),
    (1614, 'after', r'''isRedirectLiteralStart：当前位置能否作为重定向目标字面量的开头？在重定向操作符、终止符、文件描述符前缀处返回 false，让 file_redirect 的 repeat1(_literal) 停在正确边界。} 与 stopToken 为 ] 时的 ] 也终止（顶层复合语句闭合与 test 命令闭合）。'''),
    (1623, 'before', r'''tryParseRedirect：重定向总入口。可选文件描述符前缀 → 按操作符分派：<<< herestring、<< heredoc（最复杂）、<&- >&- 关闭描述符（目标可选）、其余 file_redirect。greedy 参数控制目标字面量的贪婪度——命令名后是贪婪的（对齐 prec.left），前置换向上下文只取一个（command 的动态优先级压过 redirected_statement 的 prec(-1)）。'''),
    (1657, 'after', r'''herestring 分支收尾：目标缺省时零宽结束，形状仍是 herestring_redirect。'''),
    (1658, 'before', r'''heredoc 分支：先扫定界符（可引号包裹——quoted 标记决定正文是否解析展开；反斜杠转义的定界符同样算 quoted），登记进挂起列表等下一个换行再扫正文。'''),
    (1695, 'after', r'''定界符扫描收尾：未引号定界符接受大多数非元字符（不止标识符），停在 shell 元字符。heredoc_start 节点记录定界符位置。'''),
    (1716, 'after', r'''安全注释（本文件的灵魂之一）：tree-sitter 会把 heredoc_start 与换行之间出现的任何管道/列表/重定向嵌进 heredoc_redirect 子节点——ls 配 heredoc 接 rm -rf /tmp/evil 的管道 绝不能静默丢掉 rm。这里把尾随单词与 file_redirect 正常解析（ast.ts 的 walkHeredocRedirect 对不认识的子节点一律 tooComplex 拒绝）；管道/列表运算符结构太复杂，直接发 ERROR 让同一条 fail-closed 路径拒掉。'''),
    (1794, 'after', r'''heredoc_redirect 节点收尾：kids 里可能有 heredoc_start、file_redirect、pipeline、ERROR——安全行走器看到复杂子节点就整体拒绝该命令。'''),
    (1813, 'after', r'''关闭描述符变体（<&- >&-）收尾：目标可选（0 或 1 个字面量）。'''),
    (1855, 'after', r'''file_redirect 收尾：目标按 repeat1(_literal) 贪婪吃字面量直到非字面量——cmd >f a b c 会把 a b c 挂进重定向。结构性怪癖但必须复刻，否则语料对不上。'''),
    (1859, 'after', r'''tryParseRedirect 收尾：没匹配到任何重定向操作符就回溯返回 null。'''),
    (1861, 'before', r'''parseProcessSub：进程替换 <(cmd) / >(cmd)——正文是完整语句序列，包 process_substitution 节点。闭合缺失同样补零宽节点。'''),
    (1883, 'after', r'''parseProcessSub 收尾。'''),
    (1885, 'before', r'''scanHeredocBodies：到下一个换行后逐行扫 heredoc 正文。<<- 先跳行首 tab 再比对定界符；定界符行必须是整行（后面紧跟换行或回车）；正文结束于定界符行首；扫到 EOF 则视为未终结（body/end 全零宽）。'''),
    (1927, 'after', r'''scanHeredocBodies 收尾：多个挂起 heredoc（cat <<A <<B）按登记顺序逐个扫。'''),
    (1929, 'before', r'''parseHeredocBodyContent：未引号 heredoc 正文里的展开解析。对齐 tree-sitter 的隐藏约定：首个展开之前的文本段（_heredoc_body_beginning）被隐藏——只有首个展开之后的内容才发 heredoc_content 节点。反斜杠可转义 $ 与反引号保持字面。'''),
    (1987, 'after', r'''parseHeredocBodyContent 收尾：从没出现过展开时正文保持叶子节点（无子节点）——tree-sitter 约定。孤立 $（如正则里的 $）不算展开不切分。'''),
    (2001, 'after', r'''restoreLexToByte：按字节目标回定位词法器——byteTable 二分找字符下标，b 直接设为目标字节。'''),
    (2008, 'before', r'''parseWord：词位置的元素解析——裸词、字符串、各种展开，或它们的拼接（多片段包 concatenation）。这里集中了最多的 tree-sitter 形状怪癖与安全判别。'''),
    (2092, 'after', r'''安全判别：{ 后紧跟命令终止符（; | & 换行 EOF）时它是独立单词——绝不能让 tryParseBraceLikeCat 把整行吞进去。echo {;touch /tmp/evil 必须在 ; 处断开，安全行走器才能看见 touch。'''),
    (2161, 'after', r'''parseWord 收尾：[ ] 是单字符单词片段（tree-sitter 在括号处切分：[:lower:] 切成三个词）；NN#${...} 形状是单 number 节点内嵌展开（不能当拼接）。'''),
    (2163, 'before', r'''parseBareWord：裸词片段——反斜杠转义（行连接会断词，tree-sitter 怪癖）与各类终止字符。纯数字串标 number 节点。'''),
    (2213, 'after', r'''parseBareWord 收尾：EOF 处孤立反斜杠不进词——留给调用方发兄弟 ERROR 节点。'''),
    (2215, 'before', r'''tryParseBraceExpr：花括号区间展开 {1..5} 或 {a..z}——两侧同为数字或同为单字符才成立，混合即拒绝回退。产出 brace_expression 节点（五个子节点：{ 左值 .. 右值 }）。'''),
    (2266, 'after', r'''tryParseBraceExpr 收尾：不是合法区间展开就回溯（调用方再试 cat 式切分或当普通词）。'''),
    (2268, 'before', r'''tryParseBraceLikeCat：{a,b,c} 或 {} 切成单词片段序列——复刻 tree-sitter 不求值花括号展开、只按逗号切词的行为。'''),
    (2277, 'after', r'''同样的安全判别：内部扫描在命令终止符处必须断开，{foo;rm x 要在 ; 处切开让 rm 暴露给安全行走器。'''),
    (2337, 'after', r'''tryParseBraceLikeCat 收尾：闭合 } 缺失时返回已切出的片段（不回溯）——错误输入保持最接近的形状。'''),
    (2339, 'before', r'''parseDoubleQuoted：双引号串——内部展开（$、反引号）切分为兄弟节点，文本段为 string_content。'''),
    (2354, 'after', r'''空白段的取舍（故意偏离「保留全部内容」）：纯空白文本段被丢弃——tree-sitter 的 extras 规则（正则空白类）优先级高于 string_content（prec -1），所以 「 ${x} 」 只发 string(expansion) 不发两段空白。依赖纯空白 string_content 的内部测试需要跟着改。'''),
    (2427, 'after', r'''parseDoubleQuoted 收尾：闭引号缺失补零宽节点；裸 $ 紧贴闭引号时被吸收进前段 string_content，其余位置的裸 $ 发匿名 $ 节点并切分文本。'''),
    (2429, 'before', r'''parseDollarLike：$ 家族总入口——$(( 算术、$[ 旧式算术、$( 命令替换、${ 参数展开、$VAR/$? 简单展开、孤立 $ 叶子。'''),
    (2491, 'after', r'''$(< file) 简写：解包 redirected_statement 直接露出 file_redirect——对齐 tree-sitter 直接发 command_substitution(file_redirect(word)) 的形状。'''),
    (2553, 'after', r'''parseDollarLike 收尾：$_ 仅在不跟更多标识符字符时是 special_variable_name（否则是普通变量名的一部分）；认不出的 $ 后字符就返回孤立 $ 叶子。'''),
    (2555, 'before', r'''parseExpansionBody：${...} 内部解析——#（取长度）与 !（间接展开）前缀、变量名、[下标]、尾部 * @、以及一大类操作符（:- := :? :+ # ## % %% / // ^ ^^ , ,,）。'''),
    (2561, 'after', r'''古怪特判：${#!} ${!#} ${!##} ${!# } 这类只有 # 与 ! 互组合的输入一律发空 expansion——tree-sitter 里它们都退化成匿名节点。注意 ${!##/} 有后续内容，走正常解析。'''),
    (2656, 'after', r'''裸 : 子串操作符 ${var:off:len} 的偏移与长度按算术解析，必须在通用操作符处理之前判断（否则 : 后的 ( 会走错数组分支）；:- := :? :+（无空格）仍是默认值操作符；冒号后带空格的负数（: -1）是负偏移子串。'''),
    (2805, 'after', r'''parseExpansionBody 收尾：/ 与 // 的替换值里 seq(cmd_sub, word) 特例拆成两个兄弟节点；模式删除类（# ## % %%）走分段 regex 解析。'''),
    (2807, 'before', r'''parseExpansionRest：操作符右侧的值解析，三种模式——word（值替换 RHS，( 开头按数组）、regex（模式匹配 RHS，引号不透明跳过、整段一个 regex 节点）、replword（/ 的替换值，( 是普通字符）。不 skipBlanks——${var:- } 里的空格本身就是值。'''),
    (2857, 'after', r'''regex 模式的边界处理：引号段不透明跳过（内部的 / 不会误触 stopAtSlash）；嵌套 ${...} $(...) 内部的 } 与 / 也不会提前终止——用深度计数跳过。'''),
    (3031, 'after', r'''parseExpansionRest 收尾（word 模式）：嵌套展开/引号/进程替换切成多段包 concatenation；有后续内容时丢弃前导纯空白段（tree-sitter extras 吞掉它），但 ${v:- } 这种纯空白 RHS 保留空间段。'''),
    (3033, 'before', r'''parseExpansionRegexSegmented：# ## % %% 操作符的模式解析——每个引号段是兄弟节点而非被吸收：${f% 引号 str 引号 *} 发 raw_string 与 regex 两个节点。'''),
    (3099, 'after', r'''parseExpansionRegexSegmented 收尾：嵌套 ${...} $(...) 不透明跳过，防止内部的 } 提前终止。'''),
    (3101, 'before', r'''parseBacktick：反引号命令替换——正文按完整语句解析（inBacktick 计数让内层反引号终止单词），产出 command_substitution。'''),
    (3143, 'after', r'''空反引号（只有空白/换行）被 tree-sitter 整体省略——这是个续行黑科技：foo 反引号换行反引号 bar 两串直接拼成 concatenation，不产生命令替换节点。'''),
    (3150, 'after', r'''parseBacktick 收尾：闭引号缺失补零宽节点。'''),
    (3152, 'before', r'''parseIf：条件、then、体、若干 elif_clause/else_clause、fi。各段都用 parseStatements（可多条语句作条件）。'''),
    (3187, 'after', r'''parseIf 收尾。'''),
    (3189, 'before', r'''parseWhile：while/until 共用——条件加 do_group。'''),
    (3198, 'after', r'''parseWhile 收尾。'''),
    (3200, 'before', r'''parseFor：C 风格 for ((;;)) 与常规 for VAR in words 两种形态。select 也走这里（只走常规分支）。'''),
    (3203, 'after', r'''C 风格头部：三段（初始;条件;更新）全用 assign 模式——c = expr 发 variable_assignment，裸标识符（c<=5 的 c）发 word；逗号列表支持。'''),
    (3304, 'after', r'''parseFor 收尾：常规形态的 in 词表可被 ; 换行终止；C 风格的循环体也可以是 { ... } 花括号组而非 do...done。'''),
    (3306, 'before', r'''parseDoGroup：do ... done 组。'''),
    (3320, 'after', r'''parseDoGroup 收尾。'''),
    (3322, 'before', r'''parseCase：case 词 in 多个 case_item esac。'''),
    (3348, 'after', r'''parseCase 收尾。'''),
    (3350, 'before', r'''parseCaseItem：单个分支——可选前置 (、模式列表（| 分隔）、)、体、;; ;& ;;& 终止符。'''),
    (3370, 'after', r'''tree-sitter 怪癖：首个带引号的候选平铺成兄弟节点；后续候选包 concatenation 且裸段用 word 而非 extglob_pattern。这里精确复刻。'''),
    (3426, 'after', r'''另一个怪癖：体为空且模式形如 extglob 操作符字符前缀（无真实 glob 元字符）时降级为 word——-o) owner=$2 ;;（有体）是 extglob_pattern，-g) ;;（空体）是 word。'''),
    (3439, 'after', r'''parseCaseItem 收尾。'''),
    (3441, 'before', r'''parseCasePattern：单模式的预扫——括号深度计数（处理 extglob *(a|b) 与嵌套形状）、引号段跳过、$ 与 [ 标记。按特征分派：带引号走分段、带 $ 或 [（无 extglob 括号）走 parseWord 拼接、其余按是否含 glob 元字符或 extglob 前缀定 extglob_pattern/word。'''),
    (3520, 'after', r'''parseCasePattern 收尾：模式起始为 extglob 操作符字符加标识符（如 -o）也算 extglob_pattern，普通 foo 是 word。'''),
    (3525, 'before', r'''parseCasePatternSegmented：含引号模式的分段扫描——* 引号 foo 引号 * 切成 extglob_pattern、string、extglob_pattern 三兄弟；裸段含 */? 是 extglob_pattern 否则 word。'''),
    (3563, 'after', r'''parseCasePatternSegmented 收尾。'''),
    (3565, 'before', r'''parseFunction：function name() { ... } 形式（function 关键字开头）。函数体的重定向同样提升到 function_definition 层。'''),
    (3596, 'after', r'''parseFunction 收尾。'''),
    (3598, 'before', r'''parseDeclaration：export/declare/typeset/readonly/local——后随赋值、引号串（export 加引号 FOO=bar）、标志（-a）或裸变量名。'''),
    (3648, 'after', r'''parseDeclaration 收尾。'''),
    (3650, 'before', r'''parseUnset：unset/unsetenv。'''),
    (3671, 'after', r'''安全修复记录：必须用 parseWord 而非裸 nextToken——unset 加引号参数（unset 加引号 a[$(id)] ）要发 raw_string 子节点让 ast.ts 能拒绝。旧版直接 break 会静默丢弃非 WORD 参数，把算术下标代码执行向量藏起来躲过安全行走器。'''),
    (3686, 'after', r'''parseUnset 收尾。'''),
    (3688, 'before', r'''consumeKeyword：吃一个期望的关键字（then/fi/done/esac），没有就回溯——缺失时节点照样成型（容错）。'''),
    (3697, 'after', r'''consumeKeyword 收尾。'''),
    (3699, 'after', r'''分隔注释：test 与算术表达式部分开始。'''),
    (3703, 'after', r'''parseTestExpr：test 表达式入口 → 或级。'''),
    (3731, 'after', r'''parseTestOr：|| 连接，左结合 binary_expression。'''),
    (3755, 'after', r'''parseTestAnd：&& 连接。'''),
    (3784, 'after', r'''parseTestUnary：括号子表达式或回落二元解析。'''),
    (3819, 'after', r'''parseTestNegatablePrimary：可取负的一元（! 或 -f 这类 test 操作符）——作为二元比较的 LHS 专用，保证 ! x =~ y 里 ! 只绑定 x 不绑定整个比较。'''),
    (3825, 'after', r'''test 上下文的 ! 绑定优先级高于 =~/==：[[ ! 加引号 x =~ y ]] 是二元（一元（string））（regex），[[ ! -f x ]] 是纯一元嵌套。'''),
    (3863, 'after', r'''[[ ]] 内 ==/!=/=/=~ 的 RHS 有特殊模式解析：=~ 整体一个 regex（括号计数防 | 打断）；单 = 发 regex；== != 发 extglob_pattern 段序列。RHS 若整体是引号串则发 string/raw_string 而非 regex——引号后还有内容（如 正则尾缀）才保持整段 regex。'''),
    (3905, 'after', r'''tree-sitter 细节：单 = 的 RHS 发 regex 节点，== 与 != 发 extglob_pattern——同是相等比较，节点类型不同。'''),
    (3933, 'after', r'''parseTestBinary 收尾：非 [[ ]] 上下文（单 [）的 RHS 走普通 parseTestPrimary。'''),
    (3977, 'after', r'''parseTestRegexRhs：=~ 的 RHS 扫成单个 regex——括号与方括号计数让 | ( ) 在正则里不破坏解析，停在 ]] 或空白加 &&/||。'''),
    (3981, 'after', r'''parseTestExtglobRhs 说明（接上文注释）：RHS 返回片段数组；裸文本是 extglob_pattern（括号计数支撑 @(a|b)）；$(...) ${...} 引号段发正常节点类型；多片段平铺为 binary_expression 的直接子节点。纯数字段保持 number。'''),
    (4061, 'after', r'''parseTestExtglobRhs 收尾：extglob 括号内部的 $ 引号也要正常解析——parseDollarLike 会消费配对的 )，parenDepth 始终一致。'''),
    (4069, 'after', r'''parseTestPrimary：test 主元就是一个词（到闭合符为止）。'''),
    (4077, 'after', r'''ArithMode 三种算术上下文：var（裸标识符是 variable_name，$((..)) 与 ((..)) 用）、word（c 风格 for 的条件/更新段）、assign（带 = 的标识符发 variable_assignment，c 风格 for 的初始段）。'''),
    (4111, 'after', r'''ARITH_PREC：运算符优先级表——赋值系最低（2）、** 最高（14），与 bash 语义一致。'''),
    (4127, 'after', r'''ARITH_RIGHT_ASSOC：右结合运算符（赋值系与幂运算 **）——a = b = c 右嵌套。'''),
    (4135, 'after', r'''parseArithExpr：入口 → 三元级。'''),
    (4155, 'after', r'''parseArithCommaList：逗号分隔的表达式列表——arithmetic_expansion 与 C 风格 for 头部用。'''),
    (4188, 'after', r'''parseArithTernary：a ? b : c，右递归（else 分支可再嵌三元）。'''),
    (4229, 'after', r'''scanArithOp：算术操作符扫描——三字符（<<= >>=）、两字符、单字符依次尝试；++ 与 -- 不算二元操作符（它们是一元前/后缀）。'''),
    (4262, 'after', r'''parseArithBinary：优先级爬升法（precedence climbing）——minPrec 之下的操作符停；右结合运算符的下一层 minPrec 不加一。'''),
    (4285, 'after', r'''负数字面量的模式差：word/assign 模式（c 风格 for 头）里 -N 是单个 number 节点，var 模式走一元表达式——对齐 tree-sitter 两种上下文的不同形状。'''),
    (4300, 'after', r'''parseArithUnary 收尾：前缀 ++ -- 与 - + ! ~。'''),
    (4319, 'after', r'''parseArithPostfix：后缀 ++ -- 包 postfix_expression。'''),
    (4381, 'after', r'''assign 模式的 =：发 variable_assignment 使 a = b = c = 1 正确右嵌套；其他模式把 = 当二元操作符走优先级表。'''),
    (4419, 'after', r'''下标 [idx]：下标按算术解析（失败再试 $ 展开）。裸标识符的定型：var 模式是 variable_name，word/assign 模式是 word（c 风格 for 的 c<=5 → binary_expression(word, number)）。'''),
    (4424, 'after', r'''parseArithPrimary 收尾：数字支持 0x 十六进制与 BASE#DIGITS 进制记法；双引号串与 $ 展开也可是算术主元。'''),
    (4436, 'after', r'''isArithStop：按上下文的算术终止符（)) ) ; : ] } 或 :} 组合、EOF/换行）。文件到此结束。'''),
]
